/** 1. Brand Logo (PNG) */
export function BrandLogo({ className = "size-8", alt = "Logo" }: { className?: string; alt?: string }) {
  return (
    <Image
      src={logoImg}
      alt={alt}
      width={40}
      height={40}
      className={`object-contain ${className}`}
      priority
      unoptimized
    />
  );
}

